import{_ as o,o as t,c as a,ah as n}from"./chunks/framework.Bja9t6Wf.js";const p=JSON.parse('{"title":"Audiobook Script: Episode 1 – The Whispers of Gold","description":"","frontmatter":{},"headers":[],"relativePath":"en/hoerbuch/episode-1-whispers-of-gold.md","filePath":"en/hoerbuch/episode-1-whispers-of-gold.md"}'),i={name:"en/hoerbuch/episode-1-whispers-of-gold.md"};function r(s,e,h,l,d,c){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="audiobook-script-episode-1-–-the-whispers-of-gold" tabindex="-1">Audiobook Script: Episode 1 – The Whispers of Gold <a class="header-anchor" href="#audiobook-script-episode-1-–-the-whispers-of-gold" aria-label="Permalink to &quot;Audiobook Script: Episode 1 – The Whispers of Gold&quot;">​</a></h1><p><strong>Title:</strong> <em>The Horten Mystery: A Fictional Acoustic of Power and Money</em><strong>Duration:</strong> approx. 15-20 minutes <strong>Cast:</strong> Birgit Minichmayr, August Diehl, Oliver Masucci, AI-Grok, AI-Gemini.</p><hr><h2 id="intro" tabindex="-1">[INTRO] <a class="header-anchor" href="#intro" aria-label="Permalink to &quot;[INTRO]&quot;">​</a></h2><p><strong>(Sound: The ticking of a high-end wristwatch, slowly transitioning into the sound of falling coins. Then: A cool, elegant cello melody.)</strong></p><p><strong>CHRONICLER (Oliver Masucci):</strong> They say money works. But that&#39;s a lie. Money never sleeps, yes – but it doesn&#39;t work. It lets work. And when it&#39;s completely still, late at night on a yacht on Lake Wörthersee or in a vault in Duisburg... then it whispers.</p><p><strong>AI-GEMINI (Synthetic, clear voice):</strong> System analysis started. The Horten fortune. Status 2026: A construct of history, art, and political influence. Error rate of the official truth: High.</p><hr><h2 id="act-1-the-dazzling-silence" tabindex="-1">[ACT 1: The Dazzling Silence] <a class="header-anchor" href="#act-1-the-dazzling-silence" aria-label="Permalink to &quot;[ACT 1: The Dazzling Silence]&quot;">​</a></h2><p><strong>HEIDI (Birgit Minichmayr):</strong> (With a touch of irony) Do you hear that? That&#39;s the sound of a pearl necklace sliding on silk. Helmut always said: &quot;Heidi, people talk a lot. But gold has the more beautiful voice.&quot; He was right. If you have enough of it, it even drowns out the screams of the past.</p><p><strong>(Sound: The clinking of champagne glasses, distant laughter from a gala.)</strong></p><p><strong>AI-GROK (Sarcastic, slightly distorted):</strong> Grok here. Analysis of &quot;charity&quot;: 931,000 euros to the ÖVP. Divided into 49,000-euro tranches. That&#39;s no coincidence; that&#39;s advanced pointillism. When the rain of gold falls, everyone looks up – and no one sees the mud beneath their feet.</p><hr><h2 id="act-2-the-melt-flow-of-1936" tabindex="-1">[ACT 2: The Melt Flow of 1936] <a class="header-anchor" href="#act-2-the-melt-flow-of-1936" aria-label="Permalink to &quot;[ACT 2: The Melt Flow of 1936]&quot;">​</a></h2><p><strong>(Sound: Wind blowing through an empty street. The hard clicking of boots on cobblestones.)</strong></p><p><strong>HELMUT (August Diehl):</strong> (Young, undercooled, precise) Duisburg, April 23, 1936. The contract is before me. 672,963 Reichsmarks. A bargain. Messrs. Strauß and Lauter don&#39;t tremble when signing. They are... efficient. Like me. One name is erased, a new one is painted. &quot;Horten&quot;. It sounds like &quot;Horten&quot; (hoarding). That&#39;s not a name; that&#39;s a program.</p><p><strong>CHRONICLER (Masucci):</strong> While the ink dries, families disappear. Not from the world, not yet. But from the shop windows. Market consolidation is a silent process. It doesn&#39;t need tanks. It only needs a signature and the right price at the wrong moment.</p><hr><h2 id="act-3-the-fear-in-linz" tabindex="-1">[ACT 3: The Fear in Linz] <a class="header-anchor" href="#act-3-the-fear-in-linz" aria-label="Permalink to &quot;[ACT 3: The Fear in Linz]&quot;">​</a></h2><p><strong>(Sound: Fast typing on a smartphone keyboard. WhatsApp notification sounds.)</strong></p><p><strong>AUGUST W. (August Diehl):</strong> (Hectic, whispering) &quot;You&#39;ll get everything you want anyway.&quot; – Did we really write that? My God, Thomas, we&#39;re in Linz! The judge is looking at me like I&#39;m a pickpocket. All I wanted was... regional structural development! A tax office is not a crime!</p><p><strong>AI-GROK:</strong> Update: Abuse of office is the new art form. Who needs department stores when you can control tax offices? August, sing in 49,000-euro measures. Maybe the WKStA will think it&#39;s an opera.</p><hr><h2 id="outro" tabindex="-1">[OUTRO] <a class="header-anchor" href="#outro" aria-label="Permalink to &quot;[OUTRO]&quot;">​</a></h2><p><strong>HEIDI (Minichmayr):</strong> Sleep well. The money is safe. The dots are set. And the picture? You&#39;ll only see the picture when you&#39;re far enough away.</p><p><strong>(Sound: The cello grows louder, mixed with the sound of a shredder, slowly fading out.)</strong></p><p><strong>AI-GEMINI:</strong> Session ended. To be continued.</p><hr><p><em>Script created by Volti Sodala &amp; Gemini CLI. February 2026.</em></p>',29)])])}const g=o(i,[["render",r]]);export{p as __pageData,g as default};
